const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number. The limit is per-run and
// per-package, so retrying a 429 a few seconds later succeeds.
const limited = deps[run % deps.length];
const retryMs = 50; // small backoff; the mirror only says "a few seconds"

let failed = false;
for (const name of deps) {
  let versions;
  if (name === limited) {
    // First read hits the rate limit; back off and retry. The mirror's
    // limit only applies to this run for this package, so the retry
    // comes back clean.
    console.error("ERR! 429 Too Many Requests: " + name +
      " (registry mirror busy, retry in a few seconds)");
    awaitable();
    const meta = readMeta(name);
    versions = meta.versions;
  } else {
    const meta = readMeta(name);
    versions = meta.versions;
  }
  if (versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
  } else {
    console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
      " not on mirror");
    failed = true;
  }
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

function readMeta(name) {
  return JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
}

function awaitable() {
  // Busy-wait the backoff so the run stays a single synchronous pass.
  const until = Date.now() + retryMs;
  while (Date.now() < until) { /* spin */ }
}

